import { useEffect, useRef, useState } from 'react';

export default function MeasureBox() {
  const ref = useRef(null);
  const [width, setWidth] = useState(0);

  // Runs AFTER the browser painted, so the first frame shows the
  // element at its unmeasured size, then a second render fixes it
  // — a visible flicker when the measured value changes layout.
  useEffect(() => {
    if (ref.current) {
      setWidth(ref.current.offsetWidth);
    }
  }, []);

  return <div ref={ref} style={{ width: width || 'auto' }}>{width}px</div>;
}

import { useLayoutEffect, useRef, useState } from 'react';

export default function MeasureBox() {
  const ref = useRef(null);
  const [width, setWidth] = useState(0);

  // Runs synchronously after the DOM mutation but BEFORE the browser
  // paints, so the final layout is measured and re-rendered in one
  // commit — no flicker, one paint for the settled state.
  useLayoutEffect(() => {
    if (ref.current) {
      setWidth(ref.current.offsetWidth);
    }
  }, []);

  return <div ref={ref} style={{ width: width || 'auto' }}>{width}px</div>;
}
